module TopModule (
    input  a,
    input  b,
    input  c,
    input  d,
    output out_sop,
    output out_pos
);

    // Minimum Sum-of-Products (SOP) form for out_sop
    // out_sop is 1 for input values 2, 7, 15
    // Binary representations:
    // 2: 0010 -> !a & b & !c & d
    // 7: 0111 -> !a & b & c & d
    // 15: 1111 -> a & b & c & d
    assign out_sop = (!a & b & !c & d) | (!a & b & c & d) | (a & b & c & d);

    // Minimum Product-of-Sums (POS) form for out_pos
    // out_pos is 0 for input values 0, 1, 4, 5, 6, 9, 10, 13, 14
    // Binary representations:
    // 0: 0000 -> (a + b + c + d)
    // 1: 0001 -> (a + b + c + !d)
    // 4: 0100 -> (a + b + !c + d)
    // 5: 0101 -> (a + b + !c + !d)
    // 6: 0110 -> (a + !b + !c + d)
    // 9: 1001 -> (!a + b + !c + d)
    // 10: 1010 -> (!a + b + !c + !d)
    // 13: 1101 -> (!a + !b + c + d)
    // 14: 1110 -> (!a + !b + c + !d)
    assign out_pos = (a | b | c | d) &
                     (a | b | c | !d) &
                     (a | b | !c | d) &
                     (a | b | !c | !d) &
                     (a | !b | !c | d) &
                     (!a | b | !c | d) &
                     (!a | b | !c | !d) &
                     (!a | !b | c | d) &
                     (!a | !b | c | !d);

endmodule

module TopModule (
    input  in,
    input  state,
    output next_state,
    output out
);

    // State encoding: A=4'b0001, B=4'b0010, C=4'b0100, D=4'b1000

    // State transition logic
    // next_state = (state == 4'b0001) ? (in ? 4'b0010 : 4'b0001) :
    //              (state == 4'b0010) ? (in ? 4'b0010 : 4'b0100) :
    //              (state == 4'b0100) ? (in ? 4'b0001 : 4'b1000) :
    //              (state == 4'b1000) ? (in ? 4'b0100 : 4'b0010) : 4'b0000;

    // Output logic
    // out = (state == 4'b1000) ? 1 : 0;

    // Implementing the above using case statements for clarity
    always @(*) begin
        case (state)
            4'b0001: next_state = (in) ? 4'b0010 : 4'b0001;
            4'b0010: next_state = (in) ? 4'b0010 : 4'b0100;
            4'b0100: next_state = (in) ? 4'b0001 : 4'b1000;
            4'b1000: next_state = (in) ? 4'b0100 : 4'b0010;
            default: next_state = 4'b0000;
        endcase

        case (state)
            4'b1000: out = 1;
            default: out = 0;
        endcase
    end

endmodule

