module TopModule (
    input  a,
    input  b,
    input  c,
    input  d,
    output out_sop,
    output out_pos
);

    // Minimum Sum-of-Products (SOP) form for out_sop
    // out_sop is 1 for input values 2, 7, 15
    // Binary representations:
    // 2: 0010 -> !a & b & !c & d
    // 7: 0111 -> !a & b & c & d
    // 15: 1111 -> a & b & c & d
    assign out_sop = (!a & b & !c & d) | (!a & b & c & d) | (a & b & c & d);

    // Minimum Product-of-Sums (POS) form for out_pos
    // out_pos is 0 for input values 0, 1, 4, 5, 6, 9, 10, 13, 14
    // The complement of out_sop is 1 for those values, so we use the complement of the SOP
    // out_pos = NOT(out_sop)
    assign out_pos = ~out_sop;

endmodule

