module TopModule (
    input  clk,
    input  load,
    input  [255:0] data,
    output [255:0] q
);

    // Current state of the grid
    reg [255:0] current_state;

    // Next state of the grid
    reg [255:0] next_state;

    // Internal signal to hold the next state
    reg [255:0] next_state_reg;

    // Initialize current_state on load
    always @(posedge clk) begin
        if (load) begin
            current_state <= data;
        end
    end

    // Compute next_state based on current_state
    always @(current_state) begin
        reg [255:0] next_state;
        integer i, j, k, count;

        for (i = 0; i < 16; i++) begin
            for (j = 0; j < 16; j++) begin
                count = 0;
                for (k = 0; k < 8; k++) begin
                    integer dx, dy;
                    case (k)
                        0: {dx, dy} = {1, 1};
                        1: {dx, dy} = {1, 0};
                        2: {dx, dy} = {1, -1};
                        3: {dx, dy} = {0, 1};
                        4: {dx, dy} = {0, -1};
                        5: {dx, dy} = {-1, 1};
                        6: {dx, dy} = {-1, 0};
                        7: {dx, dy} = {-1, -1};
                    endcase

                    integer x = (i + dx) % 16;
                    integer y = (j + dy) % 16;
                    integer index = x * 16 + y;
                    if (current_state[index]) count += 1;
                end

                integer index = i * 16 + j;
                if (count == 2) begin
                    next_state[index] = current_state[index];
                end else if (count == 3) begin
                    next_state[index] = 1;
                end else begin
                    next_state[index] = 0;
                end
            end
        end
        next_state_reg <= next_state;
    end

    // Update q on the positive edge of the clock
    always @(posedge clk) begin
        q <= next_state_reg;
    end

endmodule

module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output reg walk_left,
    output reg walk_right,
    output reg aaah,
    output reg digging
);

    // Define states
    typedef enum reg [2:0] {
        STATE_WALK_LEFT,
        STATE_WALK_RIGHT,
        STATE_FALLING,
        STATE_DIGGING
    } state_t;

    state_t current_state, next_state;
    reg prev_ground;
    reg prev_dig;
    reg prev_bump_left;
    reg prev_bump_right;
    reg was_walking_left;
    reg was_walking_right;

    // State transition logic
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= STATE_WALK_LEFT;
            walk_left <= 1'b1;
            walk_right <= 1'b0;
            aaah <= 1'b0;
            digging <= 1'b0;
            prev_ground <= 1'b1;
            prev_dig <= 1'b0;
            prev_bump_left <= 1'b0;
            prev_bump_right <= 1'b0;
            was_walking_left <= 1'b1;
            was_walking_right <= 1'b0;
        end else begin
            prev_ground <= ground;
            prev_dig <= dig;
            prev_bump_left <= bump_left;
            prev_bump_right <= bump_right;

            // Determine next state
            next_state = current_state;

            // Check for fall
            if (!prev_ground && ground) begin
                // Ground reappeared, resume walking
                if (was_walking_left) begin
                    next_state = STATE_WALK_LEFT;
                end else if (was_walking_right) begin
                    next_state = STATE_WALK_RIGHT;
                end
            end else if (!ground) begin
                // Falling
                next_state = STATE_FALLING;
            end else if (dig) begin
                // Start digging
                next_state = STATE_DIGGING;
            end else if (bump_left || bump_right) begin
                // Switch direction
                if (bump_left) begin
                    next_state = STATE_WALK_RIGHT;
                end else if (bump_right) begin
                    next_state = STATE_WALK_LEFT;
                end
            end

            // Update current state
            current_state <= next_state;

            // Update outputs based on state
            case (current_state)
                STATE_WALK_LEFT: begin
                    walk_left <= 1'b1;
                    walk_right <= 1'b0;
                    aaah <= 1'b0;
                    digging <= 1'b0;
                    was_walking_left <= 1'b1;
                    was_walking_right <= 1'b0;
                end
                STATE_WALK_RIGHT: begin
                    walk_left <= 1'b0;
                    walk_right <= 1'b1;
                    aaah <= 1'b0;
                    digging <= 1'b0;
                    was_walking_left <= 1'b0;
                    was_walking_right <= 1'b1;
                end
                STATE_FALLING: begin
                    walk_left <= 1'b0;
                    walk_right <= 1'b0;
                    aaah <= 1'b1;
                    digging <= 1'b0;
                end
                STATE_DIGGING: begin
                    walk_left <= 1'b0;
                    walk_right <= 1'b0;
                    aaah <= 1'b0;
                    digging <= 1'b1;
                end
            endcase
        end
    end

