    // State definition: 0 = below s[0], 1 = between s[1] and s[0], 2 = between s[2] and s[1], 3 = above s[2]
    reg [1:0] state;

    // Previous sensor state
    reg [2:0] prev_s;

    // State transitions and output logic
    always @(posedge clk) begin
        if (reset) begin
            state <= 2'd0;
            prev_s <= 3'd0;
            fr2 <= 1'b1;
            fr1 <= 1'b1;
            fr0 <= 1'b1;
            dfr <= 1'b1;
        end else begin
            // Determine current water level
            if (s[2]) begin
                // Above s[2]
                fr2 <= 1'b0;
                fr1 <= 1'b0;
                fr0 <= 1'b0;
                dfr <= 1'b0;
                state <= 2'd3;
            end else if (s[1]) begin
                // Between s[2] and s[1]
                fr2 <= 1'b0;
                fr1 <= 1'b0;
                fr0 <= 1'b1;
                dfr <= 1'b0;
                state <= 2'd2;
            end else if (s[0]) begin
                // Between s[1] and s[0]
                fr2 <= 1'b0;
                fr1 <= 1'b1;
                fr0 <= 1'b1;
                dfr <= (prev_s[0] == 1'b0) ? 1'b1 : 1'b0;
                state <= 2'd1;
            end else begin
                // Below s[0]
                fr2 <= 1'b1;
                fr1 <= 1'b1;
                fr0 <= 1'b1;
                dfr <= 1'b1;
                state <= 2'd0;
            end

            // Update previous sensor state
            prev_s <= s;
        end
    end

endmodule

module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output reg walk_left,
    output reg walk_right,
    output reg aaah,
    output reg digging
);

    // Define states
    typedef enum reg [2:0] {
        STATE_WALK_LEFT,
        STATE_WALK_RIGHT,
        STATE_FALLING,
        STATE_DIGGING
    } state_t;

    state_t current_state, next_state;
    reg prev_ground;
    reg prev_dig;
    reg prev_bump_left;
    reg prev_bump_right;
    reg was_walking_left;
    reg was_walking_right;

    // State transition logic
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= STATE_WALK_LEFT;
            walk_left <= 1'b1;
            walk_right <= 1'b0;
            aaah <= 1'b0;
            digging <= 1'b0;
            prev_ground <= 1'b1;
            prev_dig <= 1'b0;
            prev_bump_left <= 1'b0;
            prev_bump_right <= 1'b0;
            was_walking_left <= 1'b1;
            was_walking_right <= 1'b0;
        end else begin
            prev_ground <= ground;
            prev_dig <= dig;
            prev_bump_left <= bump_left;
            prev_bump_right <= bump_right;

            // Determine next state
            next_state = current_state;

            // Check for fall
            if (!prev_ground && ground) begin
                // Ground reappeared, resume walking
                if (was_walking_left) begin
                    next_state = STATE_WALK_LEFT;
                end else if (was_walking_right) begin
                    next_state = STATE_WALK_RIGHT;
                end
            end else if (!ground) begin
                // Falling
                next_state = STATE_FALLING;
            end else if (dig) begin
                // Start digging
                next_state = STATE_DIGGING;
            end else if (bump_left || bump_right) begin
                // Switch direction
                if (bump_left) begin
                    next_state = STATE_WALK_RIGHT;
                end else if (bump_right) begin
                    next_state = STATE_WALK_LEFT;
                end
            end

            // Update current state
            current_state <= next_state;

            // Update outputs based on state
            case (current_state)
                STATE_WALK_LEFT: begin
                    walk_left <= 1'b1;
                    walk_right <= 1'b0;
                    aaah <= 1'b0;
                    digging <= 1'b0;
                    was_walking_left <= 1'b1;
                    was_walking_right <= 1'b0;
                end
                STATE_WALK_RIGHT: begin
                    walk_left <= 1'b0;
                    walk_right <= 1'b1;
                    aaah <= 1'b0;
                    digging <= 1'b0;
                    was_walking_left <= 1'b0;
                    was_walking_right <= 1'b1;
                end
                STATE_FALLING: begin
                    walk_left <= 1'b0;
                    walk_right <= 1'b0;
                    aaah <= 1'b1;
                    digging <= 1'b0;
                end
                STATE_DIGGING: begin
                    walk_left <= 1'b0;
                    walk_right <= 1'b0;
                    aaah <= 1'b0;
                    digging <= 1'b1;
                end
            endcase
        end
    end

endmodule

